"use client";

import { Fragment, useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

type Status = "pending" | "running" | "success" | "error";

function WrenchIcon() {
  return (
    <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M14.7 6.3a4 4 0 0 0-5.6 5l-6.4 6.4a1.5 1.5 0 0 0 2.1 2.1l6.4-6.4a4 4 0 0 0 5-5.6l-2.5 2.5-2-2 2.5-2.5Z" />
    </svg>
  );
}

function ChevronIcon() {
  return (
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="m6 9 6 6 6-6" />
    </svg>
  );
}

function ReplayIcon() {
  return (
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M3 12a9 9 0 1 0 2.6-6.3" />
      <path d="M3 4v5h5" />
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M20 6 9 17l-5-5" />
    </svg>
  );
}

function XIcon() {
  return (
    <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M18 6 6 18M6 6l12 12" />
    </svg>
  );
}

function StatusDot() {
  return <span className="h-1.5 w-1.5 rounded-full bg-current" />;
}

function formatElapsed(ms: number) {
  return `${(ms / 1000).toFixed(1)}s`;
}

const STATUS_TONE: Record<Status, string> = {
  pending: "bg-slate-100 text-slate-500 dark:bg-white/5 dark:text-slate-400",
  running: "bg-amber-500/10 text-amber-700 dark:text-amber-400",
  success: "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400",
  error: "bg-rose-500/10 text-rose-700 dark:text-rose-400",
};

function StatusIcon({ status, shouldReduceMotion }: { status: Status; shouldReduceMotion: boolean | null }) {
  if (status === "running") {
    return (
      <motion.span
        aria-hidden
        className="h-2.5 w-2.5 rounded-full border-2 border-amber-400/30 border-t-amber-600 dark:border-t-amber-400"
        animate={shouldReduceMotion ? undefined : { rotate: 360 }}
        transition={{ duration: 0.7, repeat: Infinity, ease: "linear" }}
      />
    );
  }
  if (status === "success") return <CheckIcon />;
  if (status === "error") return <XIcon />;
  return <StatusDot />;
}

function StatusLabel({ status }: { status: Status }) {
  if (status === "pending") return <>Pending</>;
  if (status === "running") return <>Running</>;
  if (status === "success") return <>Success</>;
  return <>Error</>;
}

function KeyValueRows({ data }: { data: Record<string, string> }) {
  return (
    <div className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1.5">
      {Object.entries(data).map(([key, value]) => (
        <Fragment key={key}>
          <span className="font-mono text-xs text-slate-400 dark:text-slate-500">{key}</span>
          <span className="truncate font-mono text-xs text-slate-700 dark:text-slate-200">{value}</span>
        </Fragment>
      ))}
    </div>
  );
}

export function Tool({
  name,
  input,
  outcome,
  output,
  autoPlay = true,
}: {
  /** The tool/function name, shown in monospace. */
  name: string;
  input: Record<string, string>;
  outcome: "success" | "error";
  /** A key-value result for "success", or an error message string for "error". */
  output: Record<string, string> | string;
  autoPlay?: boolean;
}) {
  const [playId, setPlayId] = useState(0);
  return (
    <ToolRun key={playId} name={name} input={input} outcome={outcome} output={output} autoPlay={autoPlay} onReplay={() => setPlayId((id) => id + 1)} />
  );
}

function ToolRun({
  name,
  input,
  outcome,
  output,
  autoPlay,
  onReplay,
}: {
  name: string;
  input: Record<string, string>;
  outcome: "success" | "error";
  output: Record<string, string> | string;
  autoPlay: boolean;
  onReplay: () => void;
}) {
  const [status, setStatus] = useState<Status>(autoPlay ? "pending" : outcome);
  const [expanded, setExpanded] = useState(true);
  const [elapsedMs, setElapsedMs] = useState(0);
  const startRef = useRef(0);
  const shouldReduceMotion = useReducedMotion();
  const panelId = "tool-panel";
  const done = status === "success" || status === "error";

  useEffect(() => {
    if (!autoPlay) return;
    const t1 = setTimeout(() => setStatus("running"), shouldReduceMotion ? 20 : 350);
    const t2 = setTimeout(() => setStatus(outcome), shouldReduceMotion ? 40 : 1650);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
    };
  }, [autoPlay, outcome, shouldReduceMotion]);

  useEffect(() => {
    if (status !== "running") return;
    startRef.current = performance.now();
    let raf: number;
    const tick = () => {
      setElapsedMs(performance.now() - startRef.current);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [status]);

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <div className="flex items-center gap-1 p-2">
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          aria-expanded={expanded}
          aria-controls={panelId}
          className="flex flex-1 items-center gap-2.5 rounded-lg px-2 py-1.5 text-left transition-colors hover:bg-black/[0.03] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/5"
        >
          <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-slate-900/5 text-slate-500 dark:bg-white/10 dark:text-slate-400">
            <WrenchIcon />
          </span>
          <span className="flex-1 truncate font-mono text-sm font-medium text-slate-800 dark:text-slate-100">{name}</span>
          <motion.span
            layout
            transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
            className={`inline-flex shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${STATUS_TONE[status]}`}
          >
            <StatusIcon status={status} shouldReduceMotion={shouldReduceMotion} />
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.span
                key={status}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
                animate={{ opacity: 1, y: 0 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4 }}
                transition={{ duration: 0.15 }}
              >
                <StatusLabel status={status} />
                {status === "running" && ` · ${formatElapsed(elapsedMs)}`}
                {done && ` · ${formatElapsed(elapsedMs)}`}
              </motion.span>
            </AnimatePresence>
          </motion.span>
          <motion.span
            animate={{ rotate: expanded ? 180 : 0 }}
            transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
            className="shrink-0 text-slate-400"
          >
            <ChevronIcon />
          </motion.span>
        </button>
        {done && autoPlay && (
          <button
            type="button"
            onClick={onReplay}
            aria-label="Run again"
            className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ReplayIcon />
          </button>
        )}
      </div>

      <AnimatePresence initial={false}>
        {expanded && (
          <motion.div
            id={panelId}
            role="region"
            aria-label="Tool call details"
            initial={shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
            animate={shouldReduceMotion ? { opacity: 1 } : { height: "auto", opacity: 1 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
            transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.45, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.3, ease: [0.22, 1, 0.36, 1] } }}
            className="overflow-hidden border-t border-slate-100 dark:border-white/5"
          >
            <motion.div
              initial={shouldReduceMotion ? undefined : { y: -10 }}
              animate={{ y: 0 }}
              transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.4, ease: [0.22, 1, 0.36, 1], delay: 0.08 }}
              className="flex flex-col gap-3 px-4 py-3"
            >
              <div>
                <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">Input</p>
                <KeyValueRows data={input} />
              </div>
              <AnimatePresence>
                {status === "success" && typeof output === "object" && (
                  <motion.div
                    initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
                  >
                    <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">Output</p>
                    <KeyValueRows data={output} />
                  </motion.div>
                )}
                {status === "error" && typeof output === "string" && (
                  <motion.div
                    initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
                  >
                    <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">Error</p>
                    <p className="rounded-lg border border-rose-500/20 bg-rose-500/5 px-3 py-2 text-xs leading-relaxed text-rose-700 dark:text-rose-400">
                      {output}
                    </p>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
